// Monta o HTML do PDF a partir do relatório devolvido pela API.
// Manter a montagem aqui (e não na API) permite ajustar o layout do
// PDF sem redeploy do back-end.
const r = $json.data ?? $json;

const lista = (itens) =>
  (itens ?? []).map((i) => `<li>${i}</li>`).join('') || '<li>—</li>';

const html = `<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8">
<style>
  body { font-family: system-ui, sans-serif; color:#1a1a1a; padding:40px; }
  h1 { font-size:24px; margin-bottom:4px; }
  .periodo { color:#666; font-size:13px; margin-bottom:24px; }
  h2 { font-size:16px; margin-top:24px; }
  .metricas { display:flex; gap:24px; margin:16px 0; }
  .metrica { background:#f5f5f5; padding:12px 16px; border-radius:8px; }
  .valor { font-size:22px; font-weight:600; }
  .rotulo { font-size:11px; color:#666; text-transform:uppercase; }
</style></head><body>
  <h1>Relatório semanal — Atlas</h1>
  <div class="periodo">${r.periodStart ?? ''} a ${r.periodEnd ?? ''}</div>
  <p>${r.summary ?? ''}</p>
  <div class="metricas">
    <div class="metrica"><div class="valor">${r.evolution?.workoutsCompleted ?? 0}</div><div class="rotulo">Treinos</div></div>
    <div class="metrica"><div class="valor">${Math.round(r.evolution?.adherencePercent ?? 0)}%</div><div class="rotulo">Aderência</div></div>
    <div class="metrica"><div class="valor">${r.hydration?.daysGoalReached ?? r.hydrationAnalysis?.daysGoalReached ?? 0}/7</div><div class="rotulo">Meta de água</div></div>
    <div class="metrica"><div class="valor">${r.frequency?.streak ?? 0}</div><div class="rotulo">Sequência</div></div>
  </div>
  <h2>Pontos positivos</h2><ul>${lista(r.positives)}</ul>
  <h2>Pontos de atenção</h2><ul>${lista(r.negatives)}</ul>
  <h2>Hidratação</h2><p>${r.hydrationAnalysis?.comment ?? '—'}</p>
  <h2>Sugestão para a próxima semana</h2><p>${r.workoutSuggestion ?? '—'}</p>
</body></html>`;

return { json: { ...r, html } };
